// Level-up cards (legacy systems/levelup.js), generated by the sim per player:
//   new        learn a move (only while there are free slots)
//   upgrade    level up a move you have
//   evolution  a max-level move whose required stat card you've taken (always offered when ready)
//   stat       a permanent stat card for the run (capped per card)
import { openChoice } from './choices.js';
import { presentPlayers, type Ctx } from './ctx.js';
import { addMove, canLevelUp, evolutionInfo, evolveMove, levelUpMove, moveById } from './moves.js';
import { addMaxHp, hasMove, healPlayer } from './players.js';
import type { CardOption, MoveState, PlayerState } from './state.js';

interface Candidate {
  w: number;
  card: CardOption;
}

function candidates(ctx: Ctx, p: PlayerState): Candidate[] {
  const { d, rand } = ctx;
  const cfg = d.game.levelUp;
  const out: Candidate[] = [];

  // --- new moves ---
  if (p.slots.length < p.maxSlots) {
    // No more buffs past the cap: they deal no damage, and four of them leave a run stuck.
    const buffs = p.moves.filter((m) => m.kind === 'buff').length;
    const pool = d
      .movePool(p.types)
      .filter(
        (id) =>
          !hasMove(p, id) &&
          !p.banned.includes(id) &&
          !(buffs >= cfg.maxBuffMoves && d.move(id).kind === 'buff'),
      );
    for (const id of rand.pickN(pool, cfg.newMoveCandidates)) {
      out.push({ w: cfg.weights.newMove, card: { id: `new:${id}`, type: 'new', moveId: id } });
    }
  }

  // --- evolutions: max level + the required stat card taken ---
  const waiting = new Map<string, MoveState>(); // stat card → move waiting for it
  for (const m of p.moves) {
    const ev = evolutionInfo(ctx, p, m);
    if (!ev) continue;
    if (!ev.ready) {
      waiting.set(ev.needs, m);
      continue;
    }
    out.push({
      w: cfg.weights.evolution,
      card: { id: `evolution:${m.id}`, type: 'evolution', moveId: m.id },
    });
  }

  // --- upgrades of moves you have ---
  for (const m of p.moves) {
    if (!canLevelUp(ctx, m)) continue;
    out.push({
      w: cfg.weights.moveUpgrade,
      card: { id: `upgrade:${m.id}`, type: 'upgrade', moveId: m.id, toLevel: m.level + 1 },
    });
  }

  // --- stats: capped per card; the ones that unlock an evolution are always in ---
  const room = (c: (typeof cfg.statCards)[number]) =>
    !c.maxPicks || (p.statsTaken[c.id] ?? 0) < c.maxPicks;
  const stats = rand
    .pickN(
      cfg.statCards.filter((c) => !waiting.has(c.id) && room(c)),
      cfg.statCandidates,
    )
    .concat(cfg.statCards.filter((c) => waiting.has(c.id)));
  for (const c of stats) {
    const evoFor = waiting.get(c.id);
    out.push({
      w: evoFor
        ? cfg.weights.statForEvolution
        : p.slots.length < p.maxSlots
          ? cfg.weights.statWithFreeSlots
          : cfg.weights.stat,
      card: {
        id: `stat:${c.id}`,
        type: 'stat',
        statId: c.id,
        ...(evoFor ? { unlocksEvolutionOf: evoFor.id } : {}),
      },
    });
  }
  return out;
}

/** Up to `cardsOffered` distinct cards, picked by weight; a ready evolution is always one. */
export function offerCards(ctx: Ctx, p: PlayerState): CardOption[] {
  const n = ctx.d.game.levelUp.cardsOffered;
  const pool = candidates(ctx, p);
  const picked: CardOption[] = [];
  const used = new Set<string>();
  const evo = pool.findIndex((c) => c.card.type === 'evolution');
  if (evo >= 0) {
    const [c] = pool.splice(evo, 1);
    if (c) {
      used.add(c.card.id);
      picked.push(c.card);
    }
  }
  while (picked.length < n && pool.length) {
    const total = pool.reduce((a, c) => a + c.w, 0);
    let r = ctx.rand() * total;
    let idx = 0;
    for (let i = 0; i < pool.length; i++) {
      r -= pool[i]?.w ?? 0;
      if (r <= 0) {
        idx = i;
        break;
      }
    }
    const [c] = pool.splice(idx, 1);
    if (!c || used.has(c.card.id)) continue;
    used.add(c.card.id);
    picked.push(c.card);
  }
  return picked;
}

export function applyCard(ctx: Ctx, p: PlayerState, card: CardOption): void {
  const m = card.moveId ? moveById(p, card.moveId) : undefined;
  switch (card.type) {
    case 'new':
      if (card.moveId) addMove(ctx, p, card.moveId);
      return;
    case 'upgrade':
      if (m) levelUpMove(ctx, p, m);
      return;
    case 'evolution':
      if (m) evolveMove(ctx, p, m);
      return;
    case 'stat': {
      if (!card.statId) return;
      const c = ctx.d.statCard(card.statId);
      const e = c.effect;
      if (e.type === 'maxHp') addMaxHp(p, e.value);
      else if (e.type === 'heal') healPlayer(ctx, p, p.maxHp * e.maxHpFraction);
      else {
        let v = e.op === 'mul' ? p[e.stat] * e.value : p[e.stat] + e.value;
        if (e.cap !== undefined) v = Math.min(e.cap, v);
        p[e.stat] = v;
      }
      p.statsTaken[c.id] = (p.statsTaken[c.id] ?? 0) + 1;
    }
  }
}

/** Hands out the next round of level-up cards, one choice per player, when nothing is pending. */
export function maybeLevelUp(ctx: Ctx): void {
  const { s } = ctx;
  if (s.pendingLevels <= 0 || s.pendingChoices.length) return;
  const players = presentPlayers(s);
  // Never open cards with everyone down (dying and picking up XP on the same tick).
  if (!players.length || players.every((p) => p.dead)) return;
  s.pendingLevels--;
  for (const p of players) {
    openChoice(ctx, {
      kind: 'level-up',
      playerId: p.id,
      level: s.team.level - s.pendingLevels,
      options: offerCards(ctx, p),
    });
  }
}
